AArch64 to PPC

"MOV %r,&c" -> "li %r,&c"
"STR %r,[%a]" -> "stw %r,0(%a)"
"LDR %r,[%a]" -> "lwz %r,0(%a)"
"STLR %r,[%a]" -> "lwsync; stw %r,0(%a)"
"LDAR %r,[%a]" -> "lwz %r,0(%a); lwsync"
"LDAPR %r,[%a]" -> "lwz %r,0(%a); lwsync"
"DMB SY" -> "sync"
"DMB LD" -> "lwsync"
"DMB ST" -> "lwsync"
# The C/C++ acquire/release mapping of the pair, to match this file's other
# rules: lwsync either side, never a leading sync. A negative control.
"LDXR %r,[%a]; STXR W%s,W%v,[%a]" -> "lwarx %r,r0,%a; li %s,1; stwcx. %v,r0,%a; bne xd; li %s,0; xd:"
"LDAXR %r,[%a]; STXR W%s,W%v,[%a]" -> "lwarx %r,r0,%a; lwsync; li %s,1; stwcx. %v,r0,%a; bne xd; li %s,0; xd:"
"LDXR %r,[%a]; STLXR W%s,W%v,[%a]" -> "lwsync; lwarx %r,r0,%a; li %s,1; stwcx. %v,r0,%a; bne xd; li %s,0; xd:"
"LDAXR %r,[%a]; STLXR W%s,W%v,[%a]" -> "lwsync; lwarx %r,r0,%a; lwsync; li %s,1; stwcx. %v,r0,%a; bne xd; li %s,0; xd:"
